    {
      "id": "four-dimension-inequality",
      "insight": "Present a unified visual narrative showing internet penetration gaps across all four dimensions (income, age, urban-rural, region) so the viewer can compare the magnitude of each divide at a glance"
    },
    {
      "id": "income-gradient-gap",
