[metadata] {"type": "create", "filePath": "/app/output/internet-divide-dashboard.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Internet Penetration Inequality — Global Digital Divide 2023</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
  <script src="/app/libs/chart.js"></script>
  <style>
    :root {
      --bg: #f8f7f4;
      --surface: #ffffff;
      --border: rgba(0,0,0,0.08);
      --text: #1a1a1a;
      --text-dim: #5c5c5c;
      --text-muted: #8a8a8a;

      --ssa: #c2410c;
      --ssa-light: rgba(194,65,12,0.12);
      --sia: #0891b2;
      --sia-light: rgba(8,145,178,0.12);
      --eur: #334155;
      --eur-light: rgba(51,65,85,0.10);
      --nam: #be123c;
      --nam-light: rgba(190,18,60,0.12);

      --gold: #d4a73a;
      --gold-light: rgba(212,167,58,0.15);
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: 'IBM Plex Sans', system-ui, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.4;
      padding: 32px;
      min-height: 100vh;
    }

    .dashboard {
      max-width: 1400px;
      margin: 0 auto;
    }

    .header {
      margin-bottom: 28px;
      border-bottom: 2px solid var(--text);
      padding-bottom: 16px;
    }

    .header__eyebrow {
      font-family: 'IBM Plex Mono', monospace;
      font-size: 11px;
      font-weight: 500;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 6px;
    }

    .header__title {
      font-size: 28px;
      font-weight: 700;
      letter-spacing: -0.02em;
      color: var(--text);
      margin-bottom: 4px;
    }

    .header__subtitle {
      font-size: 14px;
      color: var(--text-dim);
    }

    .grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-template-rows: auto auto;
      gap: 20px;
    }

    .panel {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 20px;
    }

    .panel--hero {
      grid-column: 1 / -1;
      padding: 24px;
    }

    .panel__header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      margin-bottom: 16px;
    }

    .panel__label {
      font-family: 'IBM Plex Mono', monospace;
      font-size: 10px;
      font-weight: 500;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 4px;
    }

    .panel__title {
      font-size: 15px;
      font-weight: 600;
      color: var(--text);
    }

    .panel__desc {
      font-size: 12px;
      color: var(--text-dim);
      margin-top: 2px;
    }

    .chart-wrap {
      position: relative;
      height: 220px;
